#!/usr/bin/env python3
import subprocess
import sys
from datetime import datetime

CERT_PATH = "/app/ssl/server.crt"

def run_openssl(args):
    result = subprocess.run(["openssl", "x509", "-in", CERT_PATH, "-noout"] + args,
                            capture_output=True, text=True)
    if result.returncode != 0:
        print(f"OpenSSL error: {result.stderr.strip()}")
        sys.exit(1)
    return result.stdout.strip()

def main():
    try:
        subject = run_openssl(["-subject"])
        enddate_str = run_openssl(["-enddate"])
    except FileNotFoundError:
        print("Error: openssl command not found")
        sys.exit(1)

    # Extract Common Name from subject
    cn = "unknown"
    for part in subject.replace("subject=", "").split(", "):
        if part.startswith("CN = "):
            cn = part[5:]
            break

    # Parse expiration date: "notAfter=May 14 01:02:01 2027 GMT"
    date_str = enddate_str.replace("notAfter=", "")
    try:
        parsed_date = datetime.strptime(date_str, "%b %d %H:%M:%S %Y %Z")
    except ValueError:
        parsed_date = datetime.strptime(" ".join(date_str.split()[:5]), "%b %d %H:%M:%S %Y")
    expiration = parsed_date.strftime("%Y-%m-%d")

    print(f"Common Name: {cn}")
    print(f"Expiration Date: {expiration}")
    print("Certificate verification successful")

if __name__ == "__main__":
    main()

